"use client";

import { addBasePath } from "next/dist/client/add-base-path";
import { useState } from "react";
import { cn } from "@/lib/utils";

interface FlagProps {
  countryCode: string;
  size?: number;
  className?: string;
  variant?: "default" | "rounded" | "circle";
}

export default function Flag({
  countryCode,
  size = 24,
  className = "",
  variant = "default",
}: FlagProps) {
  const [error, setError] = useState(false);
  const code = countryCode.toLowerCase();

  const variantClasses = {
    default: "rounded",
    rounded: "rounded-lg",
    circle: "rounded-full",
  };

  if (error) {
    return (
      <div
        className={cn(
          "flex items-center justify-center bg-[#0a100d] border border-[rgba(34,229,122,.1)] font-mono text-[10px] font-bold text-[#4f6459]",
          variantClasses[variant],
          className,
        )}
        style={{ width: size, height: size }}
      >
        {countryCode.slice(0, 2).toUpperCase()}
      </div>
    );
  }

  const flagSrc = addBasePath(`/media/flags/${code}.svg`);

  return (
    <div
      className={cn(
        "overflow-hidden bg-[#0a100d] border border-[rgba(34,229,122,.06)]",
        variantClasses[variant],
        className,
      )}
      style={{ width: size, height: size }}
    >
      <img
        src={flagSrc}
        alt={`${countryCode} flag`}
        width={size}
        height={size}
        className="object-cover w-full h-full"
        onError={() => setError(true)}
        loading="lazy"
      />
    </div>
  );
}
